import { Field, MerkleTree, Provable } from 'o1js';
import { syntheticRecords } from '../src/fixtures.js';
import { MembershipProgram, MembershipQuery } from '../src/membership.js';
import { membershipProgramForHeight } from '../src/membership-height.js';
import { EncodedRecord, encodeRecord, encodedRecordCommitment, hashIdentifier } from '../src/records.js';
import { heightSweepProtocol } from '../src/experiments/height-sweep.js';

// Constraint evaluation only; no proof is generated by these tests.
describe('membership statement at configurable tree heights', () => {
  test('height 11 compiles to exactly the published MembershipProgram circuit', async () => {
    const published = (await MembershipProgram.analyzeMethods()).proveRecord;
    const rebuilt = (await membershipProgramForHeight(11).program.analyzeMethods()).proveRecord;
    expect(rebuilt.rows).toBe(published.rows);
    expect(rebuilt.digest).toBe(published.digest);
  });

  test('each extra level only adds path-hashing rows', async () => {
    const r11 = (await membershipProgramForHeight(11).program.analyzeMethods()).proveRecord.rows;
    const r12 = (await membershipProgramForHeight(12).program.analyzeMethods()).proveRecord.rows;
    expect(r12).toBeGreaterThan(r11);
    expect(r12 - r11).toBeLessThan(32);
  });

  test('rejects heights outside the SDK range', () => {
    expect(() => membershipProgramForHeight(1)).toThrow(/tree height/);
    expect(() => membershipProgramForHeight(257)).toThrow(/tree height/);
    expect(() => membershipProgramForHeight(11.5)).toThrow(/tree height/);
  });

  describe('constraints at height 16', () => {
    const height = 16;
    const { Witness, program } = membershipProgramForHeight(height);
    const records = syntheticRecords(4, 20261014);
    const salts = records.map((_, i) => Field(101 + i));
    const encoded = records.map(encodeRecord);
    const tree = new MerkleTree(height);
    encoded.forEach((e, i) => tree.setLeaf(BigInt(i), encodedRecordCommitment(e, salts[i])));
    const query = (root: Field, id: string) => new MembershipQuery({ root, requestedRecordIdHash: hashIdentifier(id) });
    async function check(q: MembershipQuery, index: number, salt = salts[index]) {
      const witness = new Witness(tree.getWitness(BigInt(index)));
      await Provable.runAndCheck(async () => {
        await program.rawMethods.proveRecord(
          Provable.witness(MembershipQuery, () => q),
          Provable.witness(EncodedRecord, () => encoded[index]),
          Provable.witness(Field, () => salt),
          Provable.witness(Witness, () => witness)
        );
      });
    }
    test('accepts a registered record', async () => {
      await expect(check(query(tree.getRoot(), records[2].recordId), 2)).resolves.toBeUndefined();
    });
    test('rejects a different requested record', async () => {
      await expect(check(query(tree.getRoot(), records[1].recordId), 2)).rejects.toThrow();
    });
    test('rejects a wrong root and a changed salt', async () => {
      await expect(check(query(Field(7), records[2].recordId), 2)).rejects.toThrow();
      await expect(check(query(tree.getRoot(), records[2].recordId), 2, Field(999))).rejects.toThrow();
    });
  });

  test('sweep protocol keeps the same records at every height and fits capacity', () => {
    const p = heightSweepProtocol(false);
    expect(p).toMatchObject({ protocol: 'height-sweep-v1', reportable: true, records: 1000, proofMeasured: 10, verifications: 3 });
    for (const h of p.heights) expect(2 ** (h - 1)).toBeGreaterThanOrEqual(p.records);
    expect(heightSweepProtocol(true).reportable).toBe(false);
  });
});
